// "Validate & Map" Code node (Run Once for All Items).
// Reads the mapping from the Settings node and every row from Extract CSV.
// Each output item is one CSV row: mapped DB fields + _line, _valid, _errors.
const s = $('Settings').first().json;
const rows = $('Extract CSV').all().map(i => i.json);
const map = s.columnMap || {};
const required = new Set(s.required || []);
const types = s.types || {};
const maxLength = s.maxLength || {};

if (!rows.length) throw new Error('The CSV has no data rows.');

// Fail fast if the CSV header doesn't contain a mapped column: that's a setup problem, not a bad row.
const header = Object.keys(rows[0]);
const missing = Object.keys(map).filter(c => !header.includes(c));
if (missing.length) {
  throw new Error(`CSV is missing mapped column(s): ${missing.join(', ')}. Found: ${header.join(', ')}. Update columnMap in the Settings node.`);
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function toDate(v) {
  let y, m, d;
  let r = v.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (r) [, y, m, d] = r;
  else if ((r = v.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/))) {
    // Day-first by default (DD/MM/YYYY); set "dayFirst": false in Settings for MM/DD/YYYY files.
    [, d, m, y] = r;
    if (s.dayFirst === false) [d, m] = [m, d];
  } else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

function convert(type, v) {
  switch (type) {
    case 'integer': return /^-?\d+$/.test(v) ? parseInt(v, 10) : undefined;
    case 'number': {
      const n = v.replace(/,/g, '');
      return /^-?\d+(\.\d+)?$/.test(n) ? Number(n) : undefined;
    }
    case 'date': return toDate(v) ?? undefined;
    case 'email': return EMAIL.test(v) ? v.toLowerCase() : undefined;
    case 'boolean': {
      const b = v.toLowerCase();
      if (['true', 'yes', '1', 'y'].includes(b)) return 1;
      if (['false', 'no', '0', 'n'].includes(b)) return 0;
      return undefined;
    }
    default: return v;
  }
}

return rows.map((row, i) => {
  const out = {};
  const errors = [];
  for (const [csvCol, dbCol] of Object.entries(map)) {
    const raw = row[csvCol] == null ? '' : String(row[csvCol]).trim();
    if (raw === '') {
      if (required.has(dbCol)) errors.push(`${csvCol}: required`);
      out[dbCol] = null;
      continue;
    }
    const value = convert(types[dbCol], raw);
    if (value === undefined) {
      errors.push(`${csvCol}: "${raw}" is not a valid ${types[dbCol]}`);
      continue;
    }
    if (maxLength[dbCol] && String(value).length > maxLength[dbCol]) {
      errors.push(`${csvCol}: longer than ${maxLength[dbCol]} characters`);
      continue;
    }
    out[dbCol] = value;
  }
  return { json: { ...out, _line: i + 2, _valid: errors.length === 0, _errors: errors.join('; ') } };
});

return $input.all().map(i => {
  const { _line, _valid, _errors, ...row } = i.json;
  return { json: row };
});

// "Build Report" Code node (Run Once for All Items).
// Collects rows skipped by validation plus rows MySQL rejected, and returns:
//   json:   a summary (total / inserted / skipped)
//   binary: error_log.csv (only the header line when nothing failed)
const all = $('Validate & Map').all().map(i => i.json);
const invalid = all.filter(r => !r._valid).map(r => ({ line: r._line, stage: 'validation', error: r._errors }));

// Valid rows reach MySQL in order, one result item each. A rejected row comes back with an `error` field.
const valid = all.filter(r => r._valid);
let dbResults = [];
try { dbResults = $('Insert into MySQL').all().map(i => i.json); } catch (e) { /* no valid rows: MySQL never ran */ }
const rejected = [];
dbResults.forEach((res, idx) => {
  if (res && res.error) {
    const src = valid[idx] || {};
    const msg = typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error));
    rejected.push({ line: src._line ?? '', stage: 'database', error: msg });
  }
});

const errors = [...invalid, ...rejected].sort((a, b) => a.line - b.line);
const inserted = valid.length - rejected.length;

const esc = v => {
  const s = String(v ?? '');
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};
const csv = ['line,stage,error', ...errors.map(e => [e.line, e.stage, e.error].map(esc).join(','))].join('\n') + '\n';

return [{
  json: {
    total_rows: all.length,
    inserted,
    skipped: errors.length,
    table: $('Settings').first().json.table,
    message: `${inserted} of ${all.length} rows imported into ${$('Settings').first().json.table}. ${errors.length} skipped.`,
  },
  binary: {
    data: await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), 'error_log.csv', 'text/csv'),
  },
}];
